import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        PrintWriter writer = new PrintWriter(System.out);
        Solver solver = new Solver();
        solver.solve(scanner, writer);
        writer.close();
    }

    static class Solver {
        public void solve(Scanner in, PrintWriter out) {
            int n = in.nextInt();
            String s = in.next();
            int winCount = 0, maxLength = 0;
            int startIdx = 0, endIdx = 0;
            while (s.contains("__")) s = s.replace("__", "_");
            n = s.length();

            if (s.charAt(startIdx) == '(') {
                while (endIdx < n && s.charAt(endIdx) != ')') endIdx++;
                if (endIdx < n && s.charAt(endIdx) == ')') {
                    String temp = s.substring(startIdx + 1, endIdx);
                    if (!temp.contains("_") && temp.length() > 0)
                        winCount++;
                    else {
                        String[] tokens = temp.split("_");
                        winCount += tokens.length;
                    }
                    startIdx = endIdx + 1;
                }
            }

            for (int i = 0; i < n; i++) {
                if (s.charAt(i) == '(') {
                    int j = i;
                    while (j < n && s.charAt(j) != ')') j++;
                    if (j < n && s.charAt(j) == ')') {
                        String temp = s.substring(i + 1, j);
                        if (!temp.contains("_") && temp.length() > 0)
                            winCount++;
                        else {
                            String[] tokens = temp.split("_");
                            winCount += tokens.length;
                        }
                        i = j;
                    }
                }
            }

            while (s.contains("(") || s.contains(")")) {
                s = s.replaceAll("\\([^\\(]*\\)", "_");
            }

            String[] parts = s.split("_");
            for (String part : parts) {
                if (part.length() > maxLength)
                    maxLength = part.length();
            }

            out.println(maxLength + " " + winCount);
        }
    }
}
